   report['rays']=await asyncio.wait_for(page.evaluate('(c)=>probe.upperRayFixtures(c)',guards['controls']),120);assert report['rays']['error']==0;save();print('ACTUAL UPPER ASSEMBLY RAYS',len(report['rays']['points']),flush=True)
