   report['cost']['medianMs']={k:statistics.median(v['stats']['wallMs']for v in report['cost'][k])for k in ['visible','hidden']};report['cost']['deltaMs']=report['cost']['medianMs']['visible']-report['cost']['medianMs']['hidden']
   await page.evaluate("probe.visible=['evidence-plan','evidence-upper-reference'];Object.assign(probe.renderer.options,{eye:[0,13,9],target:[0,2.9,0],fov:55*Math.PI/180})");report['core']=await page.evaluate('probe.upperDraw({width:640})');await page.locator('#view').screenshot(path=str(out/'upper-core-holes.png'));assert report['core']['ids'].get('2900',0)>100
   await page.evaluate("probe.visible=['evidence-plan'];Object.assign(probe.renderer.options,{eye:[-18,22,18],target:[-5,0,0],fov:45*Math.PI/180})");report['cutaway']=await page.evaluate('probe.upperDraw({width:640})');assert not report['cutaway']['ids'].get('2900',0);await page.locator('#view').screenshot(path=str(out/'same-model-cutaway.png'));save();print('COST',json.dumps(report['cost']['medianMs']),flush=True)
